import rawFunnel from "../../data/funnel.json";
import type { FunnelData } from "./dataset-types";

// The committed synthetic dataset. Generated by `npm run seed` (data/seed.ts).
export const funnelData = rawFunnel as unknown as FunnelData;

export type {
  FunnelData,
  DayRecord,
  Cohort,
  ChannelMeta,
  ChannelKey,
  Benchmarks,
  FunnelMeta,
} from "./dataset-types";

export function dailySum(key: "signups" | "firstApiCall" | "firstIntegration", data: FunnelData = funnelData): number {
  return data.daily.reduce((s, d) => s + d[key], 0);
}

export function currentWau(data: FunnelData = funnelData): number {
  return data.daily[data.daily.length - 1].wau;
}

export function wauSeries(data: FunnelData = funnelData): number[] {
  return data.daily.map((d) => d.wau);
}
